/**
 * modules/consent.js: analytics consent banner (GDPR / ePrivacy).
 *
 * Markup is generated by src/lib/layout.mjs (renderConsent). The inline head script (analyticsHead) sets
 * Google Consent Mode v2 defaults to "denied" and defines window.loadAnalytics(); nothing from Google is
 * requested before the visitor accepts.
 *
 * Stored choice: localStorage 'consent' = 'granted' | 'denied' (try/catch; without storage the choice
 * only lasts for the page view). Hooks: [data-consent], [data-consent-choice], [data-consent-open].
 * Re-open from anywhere with document.dispatchEvent(new CustomEvent('consent:open')).
 */
import { $, $$, on } from './core.js';

const KEY = 'consent';

const read = () => {
  try {
    const v = localStorage.getItem(KEY);
    return v === 'granted' || v === 'denied' ? v : null;
  } catch {
    return null;
  }
};
const write = (v) => {
  try {
    localStorage.setItem(KEY, v);
  } catch {
    /* storage unavailable: choice applies to this page view only */
  }
};

/** Best-effort removal of Google Analytics cookies (_ga, _ga_<id>, _gid, _gat*) on this host and parent domains. */
function expireGaCookies() {
  const names = document.cookie.split(';').map((c) => c.split('=')[0].trim()).filter((n) => /^(_ga|_gid|_gat|_gcl)/.test(n));
  const host = location.hostname.split('.');
  const domains = [undefined];
  for (let i = 0; i < host.length - 1; i++) domains.push('.' + host.slice(i).join('.'));
  names.forEach((n) => domains.forEach((d) => {
    document.cookie = `${n}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/${d ? `; domain=${d}` : ''}`;
  }));
}

export function init() {
  const banner = $('[data-consent]');
  if (!banner) return;
  const buttons = $$('[data-consent-open]');
  let opener = null;

  // The footer button only makes sense when this module runs.
  buttons.forEach((b) => (b.hidden = false));

  const show = (fromUser) => {
    opener = fromUser ? document.activeElement : null;
    banner.hidden = false;
    // next frame so the transition runs
    requestAnimationFrame(() => banner.classList.add('is-in'));
    if (fromUser) $('[data-consent-choice]', banner)?.focus();
  };
  const hide = () => {
    banner.classList.remove('is-in');
    banner.hidden = true;
    if (opener && document.contains(opener)) opener.focus({ preventScroll: true });
    opener = null;
  };

  const decide = (value) => {
    write(value);
    if (value === 'granted') {
      if (typeof window.loadAnalytics === 'function') window.loadAnalytics();
    } else {
      if (typeof window.gtag === 'function') {
        window.gtag('consent', 'update', { analytics_storage: 'denied', ad_storage: 'denied', ad_user_data: 'denied', ad_personalization: 'denied' });
      }
      const id = window.analyticsIds?.ga4;
      if (id) window[`ga-disable-${id}`] = true;
      expireGaCookies();
    }
    hide();
  };

  on(banner, 'click', (event) => {
    const btn = event.target.closest('[data-consent-choice]');
    if (btn) decide(btn.dataset.consentChoice);
  });
  on(document, 'click', (event) => {
    if (event.target.closest('[data-consent-open]')) show(true);
  });
  on(document, 'consent:open', () => show(true));
  on(banner, 'keydown', (event) => {
    // Esc closes without choosing (stays "undecided": analytics remain off).
    if (event.key === 'Escape' && !banner.hidden) hide();
  });

  if (read() === null) show(false);
  else if (read() === 'granted' && typeof window.loadAnalytics === 'function') window.loadAnalytics();
}
